<div class="page-heading"><div><span class="eyebrow">Ladder</span><h1>Classement</h1><p><?= e($league['name']) ?></p></div><form method="get"><select name="league" onchange="this.form.submit()"><?php foreach($leagues as $row): ?><option value="<?= (int)$row['id'] ?>" <?= (int)$row['id']===(int)$league['id']?'selected':'' ?>><?= e($row['name']) ?></option><?php endforeach; ?></select></form></div>
<section class="panel"><div class="table-wrap"><table class="table standings-table"><thead><tr><th>#</th><th>Club</th><th>J</th><th>V</th><th>N</th><th>D</th><th>BP</th><th>BC</th><th>Diff</th><th>Pts</th><th>Forme</th></tr></thead><tbody><?php foreach($table as $row): ?><tr class="<?= (int)$row['club_id']===$context->clubId()?'is-own':'' ?> <?= $row['position']<=2?'is-top':($row['position']>=15?'is-bottom':'') ?>"><td><strong><?= (int)$row['position'] ?></strong></td><td><span class="table-club"><?= club_logo($row['slug']) ?><?= e($row['club_name']) ?></span></td><td><?= (int)$row['played'] ?></td><td><?= (int)$row['wins'] ?></td><td><?= (int)$row['draws'] ?></td><td><?= (int)$row['losses'] ?></td><td><?= (int)$row['goals_for'] ?></td><td><?= (int)$row['goals_against'] ?></td><td><?= (int)$row['goal_difference']>0?'+':'' ?><?= (int)$row['goal_difference'] ?></td><td><strong><?= (int)$row['points'] ?></strong></td><td><span class="form-dots"><?php foreach(str_split((string)$row['form']) as $result): ?><i class="result-badge result-badge--<?= strtolower($result) ?>"><?= $result==='W'?'V':($result==='D'?'N':'D') ?></i><?php endforeach; ?></span></td></tr><?php endforeach; ?></tbody></table></div><div class="panel__body standings-legend"><span>Vert : titre / montée</span><span>Rouge : relégation</span><span>V N D sur les cinq derniers matchs</span></div></section>
